//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, Docker.DotNet.dll
using System;
using System.Collections.Generic;
using Docker.DotNet.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals(); // DO NOT MODIFY THIS LINE
var startParams = Globals.ThisContainerStartParameters;

// INTERIM fix for monitors built before 2026-08-09: WinNAT rejects endpoint creation when
// PortBindings specify a host IP ("Windows does not support host IP addresses in NAT
// settings"), so strip HostIP and bind all interfaces. Monitors with the in-code Windows
// branch already send HostIP = null, making this a no-op — safe to keep or delete.
if (startParams.HostConfig?.PortBindings != null)
{
    foreach (var bindings in startParams.HostConfig.PortBindings.Values)
    {
        if (bindings == null) continue;
        foreach (var binding in bindings)
        {
            binding.HostIP = null;
        }
    }
}

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll, Docker.DotNet.dll, System.Security.Cryptography.dll, System.Net.Primitives.dll
using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
using Docker.DotNet.Models;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals(); // DO NOT MODIFY THIS LINE
var service = Globals.ThisService;
var startParams = Globals.ThisContainerStartParameters;

// ---------------------------------------------------------------------------
//  * Windows containers cannot bind-mount a SINGLE FILE, only directories, so
//    the cert cannot be mounted the way nginx's server.crt/server.key are.
//    It doesn't need to be: TCAdmin always bind-mounts the service root at
//    C:\server on a Windows-containers daemon, so everything written under
//    {RootDirectory}\iis is already visible to the container at C:\server\iis.
//  * IIS can't read a PEM off disk — HTTPS is an HTTP.SYS cert-to-port binding
//    plus a site binding, both of which must be created INSIDE the container.
//    So the cert is exported as a PFX and a bootstrap script does the import +
//    binding on every container start, before handing off to ServiceMonitor.
// ---------------------------------------------------------------------------
const string ContainerIisDir = @"C:\server\iis";

// Not a security boundary: the PFX and this password sit side by side in the
// service directory, exactly like nginx's unencrypted server.key does.
const string PfxPassword = "tcadmin";

var iisDir = Path.Combine(service.RootDirectory, "iis");
Directory.CreateDirectory(iisDir);

var pfxPath = Path.Combine(iisDir, "server.pfx");
var initPath = Path.Combine(iisDir, "iis-init.ps1");

// Address clients connect to (cert subject / SAN).
var host = service.IPAddress;
if (string.IsNullOrWhiteSpace(host)) { host = "localhost"; }
var altHost = service.HostnameOrIP;

// ---------------------------------------------------------------------------
// Generate the self-signed certificate once (idempotent). Pure .NET crypto, so
// no openssl and no container internet access are required.
// ---------------------------------------------------------------------------
if (!File.Exists(pfxPath))
{
    using (var rsa = RSA.Create(2048))
    {
        var req = new CertificateRequest("CN=" + host, rsa, HashAlgorithmName.SHA256, RSASignaturePadding.Pkcs1);
        req.CertificateExtensions.Add(new X509BasicConstraintsExtension(false, false, 0, false));
        req.CertificateExtensions.Add(new X509KeyUsageExtension(
            X509KeyUsageFlags.DigitalSignature | X509KeyUsageFlags.KeyEncipherment, false));
        req.CertificateExtensions.Add(new X509EnhancedKeyUsageExtension(
            new OidCollection { new Oid("1.3.6.1.5.5.7.3.1") }, false)); // serverAuth

        // SAN carries the IP and, when the address resolves to a name, that name too —
        // so the cert still matches when FastDL composes its URL from HostnameOrIP.
        var san = new SubjectAlternativeNameBuilder();
        san.AddDnsName(host);
        System.Net.IPAddress ip;
        if (System.Net.IPAddress.TryParse(host, out ip)) { san.AddIpAddress(ip); }
        if (!string.IsNullOrWhiteSpace(altHost) && !string.Equals(altHost, host, StringComparison.OrdinalIgnoreCase))
        {
            san.AddDnsName(altHost);
            System.Net.IPAddress altIp;
            if (System.Net.IPAddress.TryParse(altHost, out altIp)) { san.AddIpAddress(altIp); }
        }
        req.CertificateExtensions.Add(san.Build());

        using (var cert = req.CreateSelfSigned(
            DateTimeOffset.UtcNow.AddDays(-1), DateTimeOffset.UtcNow.AddYears(10)))
        {
            File.WriteAllBytes(pfxPath, cert.Export(X509ContentType.Pfx, PfxPassword));
        }
    }
}

// ---------------------------------------------------------------------------
// Container bootstrap: import the PFX into LocalMachine\My, bind it to
// 0.0.0.0:443 in HTTP.SYS, add the https site binding, then hand off to the
// image's own ServiceMonitor so the container's lifetime is unchanged.
// Rewritten on every start (static content, idempotent inside the container).
// ---------------------------------------------------------------------------
var init = new StringBuilder();
init.Append("$ErrorActionPreference = 'Continue'\r\n");
init.Append("$pfx    = '" + ContainerIisDir + @"\server.pfx'" + "\r\n");
init.Append("$appcmd = Join-Path $env:windir 'system32\\inetsrv\\appcmd.exe'\r\n");
init.Append("$appid  = '{0e4a1b9e-2b7c-4b0a-9d3f-1c5e6a7b8c90}'\r\n");
init.Append("\r\n");
init.Append("try {\r\n");
init.Append("    if (-not (Test-Path $pfx)) { throw \"Certificate not found at $pfx\" }\r\n");
init.Append("\r\n");
init.Append("    $flags = [System.Security.Cryptography.X509Certificates.X509KeyStorageFlags]'MachineKeySet,PersistKeySet'\r\n");
init.Append("    $cert  = New-Object System.Security.Cryptography.X509Certificates.X509Certificate2 -ArgumentList $pfx, '" + PfxPassword + "', $flags\r\n");
init.Append("\r\n");
init.Append("    $store = New-Object System.Security.Cryptography.X509Certificates.X509Store -ArgumentList 'My', 'LocalMachine'\r\n");
init.Append("    $store.Open('ReadWrite')\r\n");
init.Append("    $store.Add($cert)\r\n");
init.Append("    $store.Close()\r\n");
init.Append("    $thumb = $cert.Thumbprint\r\n");
init.Append("    Write-Host \"[TCAdmin] Imported certificate $thumb\"\r\n");
init.Append("\r\n");
init.Append("    & netsh http delete sslcert ipport=0.0.0.0:443 2>&1 | Out-Null\r\n");
init.Append("    & netsh http add sslcert ipport=0.0.0.0:443 certhash=$thumb appid=$appid certstorename=MY 2>&1 | Out-Null\r\n");
init.Append("    Write-Host '[TCAdmin] Bound certificate to 0.0.0.0:443'\r\n");
init.Append("\r\n");
init.Append("    $bindings = (& $appcmd list site \"Default Web Site\" /text:bindings) -join ','\r\n");
init.Append("    if ($bindings -notlike '*https*') {\r\n");
init.Append("        & $appcmd set site /site.name:\"Default Web Site\" \"/+bindings.[protocol='https',bindingInformation='*:443:']\" | Out-Null\r\n");
init.Append("        Write-Host '[TCAdmin] Added HTTPS binding to Default Web Site'\r\n");
init.Append("    } else {\r\n");
init.Append("        Write-Host '[TCAdmin] HTTPS binding already present'\r\n");
init.Append("    }\r\n");
init.Append("}\r\n");
init.Append("catch {\r\n");
init.Append("    Write-Host \"[TCAdmin] HTTPS setup failed: $($_.Exception.Message)\"\r\n");
init.Append("    Write-Host '[TCAdmin] The site is still served over HTTP.'\r\n");
init.Append("}\r\n");
init.Append("\r\n");
init.Append("if (Test-Path 'C:\\ServiceMonitor.exe') {\r\n");
init.Append("    & 'C:\\ServiceMonitor.exe' 'w3svc'\r\n");
init.Append("} else {\r\n");
init.Append("    Start-Service W3SVC\r\n");
init.Append("    while ($true) { Start-Sleep -Seconds 3600 }\r\n");
init.Append("}\r\n");
File.WriteAllText(initPath, init.ToString());

// ---------------------------------------------------------------------------
// IIS answers 404.3 for any extension that has no MIME map, which is most Fast
// Download payloads (.bsp, .bz2, .vtf, .mdl, .vpk ...). The wildcard map fixes
// that; explicit maps such as .html still win over it. Written only when
// absent so an admin can edit it in the file manager and keep the change —
// and so services created before this script existed pick it up on next start.
// ---------------------------------------------------------------------------
var wwwRoot = Path.Combine(service.RootDirectory, "wwwroot");
Directory.CreateDirectory(wwwRoot);
var webConfigPath = Path.Combine(wwwRoot, "web.config");
if (!File.Exists(webConfigPath))
{
    var webConfig =
        "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n" +
        "<configuration>\r\n" +
        "  <system.webServer>\r\n" +
        "    <staticContent>\r\n" +
        "      <!-- Serve extensions IIS has no MIME map for (FastDL payloads) instead of 404.3. -->\r\n" +
        "      <mimeMap fileExtension=\".*\" mimeType=\"application/octet-stream\" />\r\n" +
        "    </staticContent>\r\n" +
        "  </system.webServer>\r\n" +
        "</configuration>\r\n";
    File.WriteAllText(webConfigPath, webConfig);
}

// ---------------------------------------------------------------------------
// Run the bootstrap instead of the image's ENTRYPOINT (it re-launches
// ServiceMonitor itself at the end). Cmd is cleared because the blueprint's
// command line would otherwise arrive as arguments to the bootstrap script.
// ---------------------------------------------------------------------------
startParams.Entrypoint = new List<string>
{
    "powershell", "-NoProfile", "-ExecutionPolicy", "Bypass", "-NonInteractive",
    "-File", ContainerIisDir + @"\iis-init.ps1"
};
startParams.Cmd = null;

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Web.Shared.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll
using System;
using System.IO;
using System.Threading.Tasks;
using TCAdmin.SDK.Database.Entities;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals(); // DO NOT MODIFY THIS LINE
var console = Globals.ScriptConsole;
var service = Globals.ThisService;

// NOTE: IScriptConsole.WriteLine(string, params) runs string.Format on the string, so
// any literal { } would throw. Dynamic values are passed as {0} args (never concatenated
// into the format string) so paths/templates containing ${...} print safely.
console.WriteLine("🚀  Enabling Fast Downloads for this server...");
console.WriteLine();

// IIS serves {RootDirectory}\wwwroot at the site root. Fast Download files live in a
// dedicated \FastDL sub-folder (kept separate from the landing page), and the public
// URL carries the same /FastDL segment so it maps 1:1 onto the files on disk.
var fastDlPath = Path.Combine(service.RootDirectory, "wwwroot", "FastDL");

// Prefer the HTTPS endpoint (matching the nginx blueprint); fall back to HTTP when the
// blueprint has no HTTPS port allocated. Ports is a safe indexer -> 0 when key missing.
var scheme = "https";
var port = service.Ports["HTTPS"];
if (port <= 0)
{
    scheme = "http";
    port = service.Ports["HTTP"];
}

if (port <= 0)
{
    console.WriteLine("❌  This service has no allocated 'HTTPS' or 'HTTP' port.");
    console.WriteLine("     Add the port to the blueprint, then recreate the service.");
    return;
}

var host = service.HostnameOrIP; // hostname if the IP has one, otherwise the IP
if (string.IsNullOrWhiteSpace(host))
{
    console.WriteLine("❌  Could not determine the service address.");
    return;
}

var baseUrl = scheme + "://" + host + ":" + port + "/FastDL/";

// Create the storage folder if it doesn't exist (as the monitor process, the same way
// the FastDL sync engine creates its own sub-directories).
try
{
    Directory.CreateDirectory(fastDlPath);
}
catch (Exception ex)
{
    console.WriteLine("⚠️  Could not create the FastDL folder ({0}): {1}", fastDlPath, ex.Message);
    console.WriteLine("     Continuing — the sync engine will create it on first run.");
}

// Load the Server tracked in the manager's own scope and mutate THAT instance.
// (Updating the cached Globals.ThisServer would be a detached write and is rejected.)
var serverManager = Globals.ServerManager;
var server = await serverManager.GetAsync(service.ServerId);
if (server == null)
{
    console.WriteLine("❌  Could not load server id {0}.", service.ServerId);
    return;
}

server.FastDLEnabled = true;
server.FastDLPath = fastDlPath;
server.FastDLBaseUrl = baseUrl;
await serverManager.UpdateAsync(server, saveChanges: true);

console.WriteLine("✅  Fast Downloads enabled!");
console.WriteLine();
console.WriteLine("🖥️   Server      : {0}", server.Name);
console.WriteLine("📁  Storage     : {0}", fastDlPath);
console.WriteLine("🔗  Base URL    : {0}", baseUrl);
console.WriteLine("🗂️   Per-service : {0}", server.FastDLFolderTemplate);
console.WriteLine();
if (scheme == "https")
{
    console.WriteLine("🔒  The HTTPS certificate is self-signed. Game clients that validate");
    console.WriteLine("     certificates will refuse it — switch the server's Fast Download");
    console.WriteLine("     base URL to the HTTP port if downloads fail for that reason.");
    console.WriteLine();
}
console.WriteLine("⚠️   Fast Downloads are now enabled on this SERVER — but they must ALSO be");
console.WriteLine("     enabled and configured for each individual game before its services");
console.WriteLine("     will mirror and serve their files here.");
console.WriteLine("🎉  All done!");

//refAssemblies: TCAdmin.SDK.dll, TCAdmin.Docker.SDK.dll, TCAdmin.Web.Shared.dll, TCAdmin.Scripting.dll, TCAdmin.Monitor.dll
using System;
using System.IO;
using System.Threading.Tasks;
using TCAdmin.SDK.Database.Entities;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpDockerGlobals(); // DO NOT MODIFY THIS LINE
var console = Globals.ScriptConsole;
var service = Globals.ThisService;

// The folder this service's IIS container served Fast Downloads from. Must match the
// path the enable icon writes ({RootDirectory}\wwwroot\FastDL) so the guard below detects it.
var fastDlPath = Path.Combine(service.RootDirectory, "wwwroot", "FastDL");

var serverManager = Globals.ServerManager;
var server = await serverManager.GetAsync(service.ServerId);
if (server == null)
{
    // WriteLine uses {0} args (not concatenation) because the console runs string.Format.
    console.WriteLine("⚠️  Could not load server id {0}; nothing to clean up.", service.ServerId);
    return;
}

// Only clear the server-level Fast Download settings if THIS service is the one currently
// backing them (enabled + storage path points at this service's \FastDL). Separator/
// trailing-slash tolerant and case-insensitive, so a second IIS service deleting doesn't
// wipe the config a different one owns.
var currentPath = (server.FastDLPath ?? "").Replace('\\', '/').TrimEnd('/');
var thisPath = (fastDlPath ?? "").Replace('\\', '/').TrimEnd('/');

if (server.FastDLEnabled && string.Equals(currentPath, thisPath, StringComparison.OrdinalIgnoreCase))
{
    server.FastDLEnabled = false;
    server.FastDLPath = "";
    server.FastDLBaseUrl = "";
    await serverManager.UpdateAsync(server, saveChanges: true);

    console.WriteLine("🧹  Fast Downloads disabled on server '{0}'.", server.Name);
    console.WriteLine("     Storage path and base URL cleared.");
}
else
{
    console.WriteLine("ℹ️  Server Fast Downloads are not pointing at this service — left unchanged.");
}
